import { Queue } from "bullmq";

import { redis } from "../config/redis";

/**
 * ==========================================
 * PAYMENT QUEUE CONFIGURATION
 * ==========================================
 */

const PAYMENT_QUEUE_NAME =
    "payment-events";

/**
 * Payment references are generated by the
 * server and must always follow this format:
 *
 * PAY-<UUID without hyphens>
 *
 * Keep this validation here as a second layer
 * of protection even if the controller/service
 * already validates the reference.
 */
const PAYMENT_REFERENCE_REGEX =
    /^PAY-[A-Za-z0-9]{32}$/;

/**
 * Maximum number of attempts for transient
 * payment-processing failures.
 */
const MAX_ATTEMPTS = 5;

/**
 * Initial retry delay.
 *
 * BullMQ exponential backoff will increase this
 * delay after every failed attempt.
 */
const INITIAL_RETRY_DELAY = 3000;

/**
 * Maximum number of completed jobs retained.
 */
const COMPLETED_JOB_RETENTION = 100;

/**
 * Maximum number of failed jobs retained.
 */
const FAILED_JOB_RETENTION = 500;

/**
 * ==========================================
 * QUEUE
 * ==========================================
 */

export const paymentQueue =
    redis
        ? new Queue(
            PAYMENT_QUEUE_NAME,
            {
                connection: redis,

                /**
                 * Queue-level defaults.
                 *
                 * Individual jobs can override these
                 * when necessary.
                 */
                defaultJobOptions: {
                    attempts:
                        MAX_ATTEMPTS,

                    backoff: {
                        type:
                            "exponential",

                        delay:
                            INITIAL_RETRY_DELAY,
                    },

                    /**
                     * Keep a small amount of successful
                     * history for debugging/monitoring.
                     */
                    removeOnComplete:
                        COMPLETED_JOB_RETENTION,

                    /**
                     * Keep failed jobs longer so
                     * payment failures can be inspected.
                     */
                    removeOnFail:
                        FAILED_JOB_RETENTION,

                    /**
                     * Do not automatically stack
                     * unnecessary retries after the
                     * application has already determined
                     * that the job should not be retried.
                     */
                    stackTraceLimit: 10,
                },
            }
        )
        : null;

/**
 * ==========================================
 * QUEUE STATUS
 * ==========================================
 */

if (!paymentQueue) {
    console.warn(
        "[PAYMENT_QUEUE] Redis unavailable. Payment queue is disabled."
    );
} else {
    console.log(
        `[PAYMENT_QUEUE] "${PAYMENT_QUEUE_NAME}" initialized.`
    );
}

/**
 * ==========================================
 * TYPES
 * ==========================================
 */

interface PaymentJobData {
    reference: string;
}

/**
 * ==========================================
 * VALIDATE PAYMENT REFERENCE
 * ==========================================
 */

const isValidPaymentReference = (
    reference: string
): boolean => {
    return (
        typeof reference === "string" &&
        PAYMENT_REFERENCE_REGEX.test(
            reference
        )
    );
};

/**
 * ==========================================
 * ADD PAYMENT JOB
 * ==========================================
 *
 * Adds a payment-processing job to BullMQ.
 *
 * IMPORTANT:
 *
 * The payment reference is the idempotency key.
 *
 * If the same webhook is received multiple times,
 * BullMQ will not create multiple jobs because
 * the reference is used as the job ID.
 */
export const addPaymentJob = async (
    reference: string
) => {
    /**
     * ------------------------------------------
     * QUEUE AVAILABILITY
     * ------------------------------------------
     */

    if (!paymentQueue) {
        throw new Error(
            "Payment queue is not initialized."
        );
    }

    /**
     * ------------------------------------------
     * REFERENCE VALIDATION
     * ------------------------------------------
     *
     * Never allow arbitrary strings from a
     * webhook request to become queue data.
     */

    if (
        !isValidPaymentReference(
            reference
        )
    ) {
        throw new Error(
            "Invalid payment reference."
        );
    }

    /**
     * ------------------------------------------
     * NORMALIZE REFERENCE
     * ------------------------------------------
     */

    const normalizedReference =
        reference.trim();

    /**
     * ------------------------------------------
     * CREATE JOB
     * ------------------------------------------
     *
     * Using a deterministic jobId provides
     * queue-level idempotency.
     */
    try {
        const job =
            await paymentQueue.add(
                "process-payment",
                {
                    reference:
                        normalizedReference,
                } satisfies PaymentJobData,
                {
                    /**
                     * Same payment reference =
                     * same BullMQ job.
                     */
                    jobId:
                        normalizedReference,

                    /**
                     * Keep the queue from creating
                     * unnecessary delayed duplicates.
                     */
                    removeOnComplete:
                        COMPLETED_JOB_RETENTION,

                    removeOnFail:
                        FAILED_JOB_RETENTION,

                    attempts:
                        MAX_ATTEMPTS,

                    backoff: {
                        type:
                            "exponential",

                        delay:
                            INITIAL_RETRY_DELAY,
                    },

                    /**
                     * Prevent jobs from becoming
                     * infinitely old in Redis.
                     *
                     * This is primarily a safety net;
                     * payment processing itself must
                     * remain idempotent.
                     */
                    lifo: false,
                }
            );

        console.log(
            `[PAYMENT_QUEUE] Payment job queued: ${normalizedReference}`,
            {
                jobId:
                    job.id,
            }
        );

        return job;
    } catch (error) {
        console.error(
            `[PAYMENT_QUEUE] Failed to queue payment: ${normalizedReference}`,
            error instanceof Error
                ? error.message
                : error
        );

        throw error;
    }
};

/**
 * ==========================================
 * REMOVE PAYMENT JOB
 * ==========================================
 *
 * Optional administrative/helper function.
 *
 * Only use this when you explicitly want to
 * remove a pending job.
 */
export const removePaymentJob = async (
    reference: string
): Promise<boolean> => {
    if (!paymentQueue) {
        throw new Error(
            "Payment queue is not initialized."
        );
    }

    if (
        !isValidPaymentReference(
            reference
        )
    ) {
        throw new Error(
            "Invalid payment reference."
        );
    }

    const job =
        await paymentQueue.getJob(
            reference
        );

    if (!job) {
        return false;
    }

    await job.remove();

    console.log(
        `[PAYMENT_QUEUE] Removed payment job: ${reference}`
    );

    return true;
};

/**
 * ==========================================
 * QUEUE HEALTH
 * ==========================================
 *
 * Useful for monitoring/admin endpoints.
 */
export const getPaymentQueueHealth =
    async () => {
        if (!paymentQueue) {
            return {
                enabled: false,
                status: "disabled" as const,
            };
        }

        try {
            const counts =
                await paymentQueue.getJobCounts(
                    "waiting",
                    "active",
                    "completed",
                    "failed",
                    "delayed"
                );

            return {
                enabled: true,

                status: "healthy" as const,

                counts,
            };
        } catch (error) {
            console.error(
                "[PAYMENT_QUEUE] Health check failed:",
                error instanceof Error
                    ? error.message
                    : error
            );

            return {
                enabled: true,

                status: "unhealthy" as const,

                counts: null,
            };
        }
    };